def solve(inputs: dict) -> float:
    # Linear congruential generator problem
    # Start with initial value and apply recurrence for specified rounds
    X = inputs.get('initial_value', 283)
    rounds = inputs.get('rounds', 9)
    a = inputs.get('a', 800)
    c = inputs.get('c', 2900)
    m = inputs.get('m', 33500)

    for _ in range(rounds):
        X = (a * X + c) % m

    return float(X)
